      (∀ {source middle target : TypedSlottedEGraphsPaper.TypedSlotContext Ty}
          {firstRenaming : TypedSlottedEGraphsPaper.TypedSlotRenaming source middle}
          {secondRenaming : TypedSlottedEGraphsPaper.TypedSlotRenaming middle target}
