            TypedSlottedEGraphsPaper.ConcreteTypedAlphaPort policy secondRenaming middlePort right →
              TypedSlottedEGraphsPaper.ConcreteTypedAlphaPort policy (secondRenaming.comp firstRenaming) left right) ∧
        (∀ (value : TypedSlottedEGraphsPaper.ConcreteUnindexedPortCarrier signature schema),
            TypedSlottedEGraphsPaper.ConcreteUnindexedAlphaPort policy value value) ∧
          (∀ {unindexedLeft unindexedRight : TypedSlottedEGraphsPaper.ConcreteUnindexedPortCarrier signature schema},
              TypedSlottedEGraphsPaper.ConcreteUnindexedAlphaPort policy unindexedLeft unindexedRight →
                TypedSlottedEGraphsPaper.ConcreteUnindexedAlphaPort policy unindexedRight unindexedLeft) ∧
            ∀
